mapper.select:
select budget_plan_pay_detail_id as budgetPlanPayDetailId, sum(ifnull(stamp_tax,0) + ifnull(additional_tax,0)) as taxSum, sum(ifnull(risk_fund_diff,0)) as riskFundDiffSum, sum(ifnull(assessment_profit,0)) as assessmentProfitSum, sum(ifnull(expense,0)) as expenseSum from budget_plan_pay_detail_expense where 1 = 1 and deleted = 0
and budget_plan_pay_detail_id in
#{item}
and expense_date >= #{startDate}
and expense_date <= #{endDate}
group by budget_plan_pay_detail_id
